SELECT DISTINCT menu_id FROM sys_role_menu WHERE
role_id IN

    #{roleId}

SELECT  DISTINCT sm.menu_id  FROM sys_role_menu srm
JOIN sys_menu sm ON srm.menu_id= sm.menu_id
WHERE sm.disabled = false
and srm.role_id IN

    #{roleId}



    AND sm.type=#{type}


    AND sm.system=#{userType}

SELECT  DISTINCT sm.menu_code  FROM sys_role_menu srm
JOIN sys_menu sm ON srm.menu_id= sm.menu_id
WHERE sm.disabled = false
and srm.role_id IN

    #{roleId}



    AND sm.type=#{type}


    AND sm.system=#{userType}


    AND sm.is_archive_display = true

SELECT  DISTINCT menu_code  FROM sys_menu WHERE disabled = false

        AND type=#{type}


        and system = #{userType}


    	AND sm.is_archive_display = true
